const $=s=>document.querySelector(s), app=$('#app');
const API='/api';
const countryConfig={
  IN:{name:'India',employment:['Full-Time','Contract','Contract-to-Hire','Internship','Part-Time'],compensation:['Annual CTC','Monthly Salary'],currency:'INR',candidate:[['preferred_location','Preferred Location'],['notice_period','Notice Period'],['current_ctc','Current CTC'],['expected_ctc','Expected CTC'],['work_mode_preference','Work Mode Preference']]},
  US:{name:'United States',employment:['Full-Time','W2 Contract','C2C','Contract-to-Hire','Part-Time'],compensation:['Annual','Hourly'],currency:'USD',candidate:[['state','State'],['work_authorization','Work Authorization'],['availability','Availability'],['relocation_preference','Relocation Preference'],['work_mode_preference','Work Mode Preference'],['employment_preference','Employment Preference'],['expected_rate','Expected Rate'],['rate_type','Rate Type']]},
  GB:{name:'United Kingdom',employment:['Permanent','Contract','Part-Time','Internship'],compensation:['Annual','Daily','Hourly'],currency:'GBP',candidate:[['preferred_location','Preferred Location'],['notice_period','Notice Period'],['work_mode_preference','Work Mode Preference']]},
  OT:{name:'Other',employment:['Full-Time','Contract','Part-Time','Internship'],compensation:['Annual','Monthly','Hourly'],currency:'USD',candidate:[['preferred_location','Preferred Location'],['availability','Availability'],['work_mode_preference','Work Mode Preference']]}
};
const roles={requirement_vendor:{label:'Requirement Vendor',home:'/vendor/dashboard',desc:'I have hiring requirements and want sourcing partners to provide candidates.',icon:'▣'},sourcing_partner:{label:'Sourcing Partner',home:'/partner/dashboard',desc:'I source candidates for company/vendor hiring requirements.',icon:'◎'},candidate:{label:'Candidate',home:'/candidate/dashboard',desc:'I am looking for jobs and want to create my profile and apply.',icon:'◇'}};
const nav={requirement_vendor:[['Dashboard','/vendor/dashboard'],['Sourcing Partners','/vendor/partners'],['Messages','/vendor/messages']],sourcing_partner:[['Dashboard','/partner/dashboard'],['Matching Requirements','/partner/requirements'],['Working On','/partner/working'],['Candidate Inventory','/partner/candidates'],['Submissions','/partner/submissions'],['Placements & Payouts','/partner/payouts'],['Messages','/partner/messages'],['Profile','/partner/profile']],candidate:[['Home','/candidate/dashboard'],['My Profile','/candidate/profile'],['Availability','/candidate/availability'],['My Resume','/candidate/resume']]};
let session=JSON.parse(localStorage.getItem('tb_session')||'null'), selectedRole='requirement_vendor';
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className=error?'show error':'show';setTimeout(()=>t.className='',3200)}
async function api(path,opts={}){const headers={...(opts.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(session?{Authorization:`Bearer ${session.access_token}`}:{})};const r=await fetch(API+path,{...opts,headers:{...headers,...opts.headers}});if(r.status===401&&session){localStorage.removeItem('tb_session');session=null;route('/auth/login');throw Error('Session expired')}let data;try{data=await r.json()}catch{data=null}if(!r.ok)throw Error(typeof data?.detail==='string'?data.detail:data?.detail?.[0]?.msg||'Request failed');return data}
function route(path){history.pushState({},'',path);render()}window.onpopstate=render;
function rolePathAllowed(path){return !path.startsWith('/vendor')&&!path.startsWith('/partner')&&!path.startsWith('/candidate')||path.startsWith(`/${session.user.role==='requirement_vendor'?'vendor':session.user.role==='sourcing_partner'?'partner':'candidate'}`)}
function authShell(body){app.innerHTML=`<div class="auth-shell"><section class="auth-hero"><div class="brand"><span class="brand-mark">T</span>TalentBridge</div><div class="hero-copy"><div class="eyebrow" style="color:#a99fff">Recruitment, connected</div><h1>One network.<br>Better hiring.</h1><p>Requirements move faster when vendors, sourcing partners and candidates work through one clear, accountable workflow.</p></div><small>Local development MVP · Private by design</small></section><section class="auth-panel"><div class="auth-card">${body}</div></section></div>`}
function loginPage(){authShell(`<div class="eyebrow">Welcome back</div><h2>Sign in to your network</h2><p class="muted">Continue to your role-specific workspace.</p><form id="login" class="form-grid" style="margin-top:2rem"><div class="field wide"><label>Email</label><input type="email" name="email" required autocomplete="email"></div><div class="field wide"><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div><button class="btn btn-primary wide">Sign in</button></form><p class="muted">New here? <a class="text-link" href="/auth/register" data-link>Create an account</a></p>`);$('#login').onsubmit=async e=>{e.preventDefault();try{session=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});localStorage.setItem('tb_session',JSON.stringify(session));route(roles[session.user.role].home)}catch(x){toast(x.message,true)}}}
function countries(){return Object.entries(countryConfig).map(([v,x])=>`<option value="${v}">${x.name}</option>`).join('')}
function registerPage(){authShell(`<div class="eyebrow">Join the network</div><h2>How do you want to use TalentBridge?</h2><p class="muted">Choose a role. This stays attached to your account.</p><div class="role-grid">${Object.entries(roles).map(([k,r])=>`<button class="role-card ${k===selectedRole?'selected':''}" data-role="${k}"><span class="role-icon">${r.icon}</span><strong>${r.label}</strong><span>${r.desc}</span></button>`).join('')}</div><form id="register"><div id="common" class="form-grid"><div class="field"><label>Full Name</label><input name="name" required></div><div class="field"><label>${selectedRole==='requirement_vendor'?'Work ':''}Email</label><input name="email" type="email" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>Phone ${selectedRole==='requirement_vendor'?'(optional)':''}</label><input name="phone" ${selectedRole==='requirement_vendor'?'':'required'}></div></div><div id="role-fields" class="form-grid" style="margin-top:1rem">${registrationFields(selectedRole)}</div><div class="actions"><button class="btn btn-primary">Create ${roles[selectedRole].label} account</button><a class="text-link" href="/auth/login" data-link>Already have an account</a></div></form>`);document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{selectedRole=b.dataset.role;registerPage()});wireCountryFields();$('#register').onsubmit=registerSubmit}
function registrationFields(role){if(role==='requirement_vendor')return `<div class="field"><label>Company Name</label><input name="company_name" required></div><div class="field"><label>Company Type</label><select name="company_type" required><option>Staffing Company</option><option>Recruitment Agency</option><option>Consulting Company</option><option>Direct Employer</option><option>RPO</option><option>Other</option></select></div><div class="field"><label>Country</label><select name="country" required>${countries()}</select></div><div class="field"><label>City / Location</label><input name="city" required></div><div class="field"><label>Website</label><input name="website" type="url"></div><div class="field"><label>LinkedIn Company URL</label><input name="linkedin_url" type="url"></div><div class="field wide"><label>Company Description</label><textarea name="description"></textarea></div>`;if(role==='sourcing_partner')return `<div class="field"><label>Recruiter Type</label><select name="recruiter_type"><option value="individual">Individual Recruiter</option><option value="agency">Agency</option></select></div><div class="field"><label>Country</label><select name="country" required>${countries()}</select></div><div class="field"><label>City / Location</label><input name="city" required></div><div class="field"><label>Agency / Company Name</label><input name="agency_name"></div><div class="field"><label>Years of Sourcing Experience</label><input name="experience_years" type="number" min="0" step=".5"></div><div class="field"><label>Markets</label><input name="hiring_markets" placeholder="India IT, US IT"></div><div class="field"><label>Technologies</label><input name="skill_areas" placeholder="Java, Data, DevOps"></div><div class="field"><label>Role Specializations</label><input name="role_specializations" placeholder="Java Developer, Data Engineer"></div><div class="field"><label>Locations / Cities / States</label><input name="locations" placeholder="Bengaluru, Texas"></div><div class="field"><label>Employment Expertise</label><input name="employment_expertise" placeholder="W2, C2C, Full-Time"></div><div class="field"><label>Work Authorization Expertise</label><input name="work_authorization_expertise" placeholder="USC, GC, H4 EAD"></div><div class="field wide"><label>Industries</label><input name="industries" placeholder="Banking, Automotive"></div>`;return `<div class="field"><label>Country</label><select name="country" data-country required>${countries()}</select></div><div class="field"><label>City / Location</label><input name="city" required></div><div class="field"><label>Current Job Title</label><input name="current_title" required></div><div class="field"><label>Total Experience (years)</label><input name="total_experience" type="number" min="0" step=".5" required></div><div class="field"><label>Availability</label><select name="availability_status"><option value="actively_looking">Actively Looking</option><option value="open_to_right_opportunity">Open to Right Opportunity</option><option value="not_looking">Not Looking</option></select></div><div class="field wide"><label>Skills</label><input name="skills" placeholder="SQL, Power BI, Excel" required></div><div id="country-extra" class="field wide"><div class="form-grid">${candidateExtra('IN')}</div></div>`}
function candidateExtra(code,data={}){return (countryConfig[code]||countryConfig.OT).candidate.map(([k,l])=>`<div class="field"><label>${l}</label>${k==='work_authorization'?`<select name="extra_${k}"><option value="">Select</option>${['US Citizen','Green Card','H1B','H4 EAD','L2 EAD','OPT','CPT','Other'].map(x=>`<option>${x}</option>`).join('')}</select>`:`<input name="extra_${k}" value="${data[k]||''}">`}</div>`).join('')}
function wireCountryFields(){const c=$('[data-country]');if(c)c.onchange=()=>{$('#country-extra').innerHTML=`<div class="form-grid">${candidateExtra(c.value)}</div>`}}
async function registerSubmit(e){e.preventDefault();const f=new FormData(e.target),common={name:f.get('name'),email:f.get('email'),password:f.get('password'),phone:f.get('phone')||null,role:selectedRole},profile={};for(const [k,v] of f)if(!['name','email','password','phone'].includes(k))profile[k]=v;['skills','industries','skill_areas','hiring_markets','role_specializations','locations','employment_expertise','work_authorization_expertise'].forEach(k=>{if(profile[k])profile[k]=profile[k].split(',').map(x=>x.trim()).filter(Boolean)});profile.country_specific_data={};Object.keys(profile).filter(k=>k.startsWith('extra_')).forEach(k=>{profile.country_specific_data[k.slice(6)]=profile[k];delete profile[k]});try{session=await api('/auth/register',{method:'POST',body:JSON.stringify({...common,profile})});localStorage.setItem('tb_session',JSON.stringify(session));route(roles[selectedRole].home)}catch(x){toast(x.message,true)}}
function layout(content,title='TalentBridge'){const links=nav[session.user.role];app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">T</span>TalentBridge</div><nav class="nav">${links.map(([n,p])=>`<a href="${p}" data-link class="${location.pathname===p?'active':''}">${n}</a>`).join('')}</nav><div class="sidebar-footer"><div class="user-name">${session.user.name}</div><div class="user-role">${roles[session.user.role].label}</div><button class="logout" id="logout">Sign out</button></div></aside><section class="content"><header class="topbar"><button class="btn btn-ghost mobile-toggle">☰</button><b>${title}</b><span class="badge active">Development</span></header><div class="page">${content}</div></section></div>`;$('#logout').onclick=()=>{localStorage.removeItem('tb_session');session=null;route('/auth/login')};$('.mobile-toggle').onclick=()=>$('.sidebar').classList.toggle('open')}
const head=(t,s,a='')=>`<div class="page-head"><div><h1>${t}</h1><p>${s}</p></div>${a}</div>`, empty=(i,t,s,a='')=>`<div class="empty"><div class="empty-icon">${i}</div><h3>${t}</h3><p>${s}</p>${a}</div>`, badge=s=>`<span class="badge ${s}">${s.replace('_',' ')}</span>`;
function requirementCard(r,mode='browse'){const terms=r.commercial_terms;return `<article class="card"><div class="card-top"><span class="eyebrow">${r.company||'Your company'}</span>${r.match_score!=null?`<span class="badge active">${Math.round(r.match_score)}% match</span>`:badge(r.status)}</div><h3>${r.title}</h3><div class="meta"><span>⌖ ${r.city}, ${countryConfig[r.country]?.name||r.country}</span><span>${r.work_mode}</span><span>${r.employment_type}</span><span>${r.min_experience}–${r.max_experience} yrs</span></div><div class="chips">${r.required_skills.slice(0,5).map(x=>`<span class="chip">${x}</span>`).join('')}</div>${r.match_reasons?.length?`<p class="muted">Matched on ${r.match_reasons.join(' · ')}</p>`:''}${terms?`<p><b>${terms.currency} ${terms.payout_amount.toLocaleString()}</b> partner payout · ${terms.payment_trigger.replaceAll('_',' ')} + ${terms.payment_timeline_days} days</p>`:''}<div class="actions"><button class="btn btn-ghost" data-view="${r.id}">View Requirement</button>${mode==='partner'?`<button class="btn btn-primary" data-start="${r.id}">Accept Terms & Work</button>`:mode==='candidate'?`<button class="btn btn-primary" data-apply="${r.id}">Apply</button>`:''}</div></article>`}
async function dashboard(){try{const d=await api('/dashboard'), role=session.user.role;const cards=role==='requirement_vendor'?[['Active Requirements',d.active_requirements],['Total Submissions',d.applications],['Under Review',d.under_review],['Shortlisted',d.shortlisted],['Interviews',d.interview],['Selected',d.selected]]:role==='sourcing_partner'?[['Available Requirements',d.available_requirements],['Working Requirements',d.working_requirements],['Candidates Submitted',d.applications],['Under Review',d.under_review],['Shortlisted',d.shortlisted],['Selected',d.selected]]:[['Applications',d.applications],['Under Review',d.under_review],['Shortlisted',d.shortlisted],['Interviews',d.interview],['Selected',d.selected]];const cta=role==='requirement_vendor'?`<button class="btn btn-primary" data-go="/vendor/requirements/new">＋ Post Requirement</button>`:`<button class="btn btn-primary" data-go="/${role==='candidate'?'candidate/jobs':'partner/requirements'}">Browse ${role==='candidate'?'Jobs':'Requirements'}</button>`;layout(head(`Good ${new Date().getHours()<12?'morning':'afternoon'}, ${session.user.name.split(' ')[0]}`,`Here’s what is happening across your ${roles[role].label.toLowerCase()} workspace.`,cta)+`<section class="stats">${cards.map(([n,v])=>`<div class="stat"><span>${n}</span><b>${v||0}</b></div>`).join('')}</section><div class="panel"><h3>Get started</h3><p class="muted">Your activity and recent updates will appear here as the network grows.</p></div>`,'Overview');$('[data-go]').onclick=e=>route(e.target.dataset.go)}catch(x){toast(x.message,true)}}
async function requirementsPage(mode){const title=mode==='vendor'?'Requirements':mode==='partner'?'Matching Requirements':'Jobs';layout(head(title,mode==='vendor'?'Create and manage your company hiring requirements.':mode==='partner'?'Ranked by your technologies, roles, market, location, and employment expertise.':'Browse active opportunities across the network.',mode==='vendor'?'<button class="btn btn-primary" data-new>＋ Create Requirement</button>':'')+`<form id="filters" class="panel filters"><div class="field"><label>Keyword</label><input name="keyword" placeholder="Title or description"></div><div class="field"><label>Country</label><select name="country"><option value="">All countries</option>${countries()}</select></div><div class="field"><label>Location</label><input name="location"></div><div class="field"><label>Work Mode</label><select name="work_mode"><option value="">Any</option><option>Remote</option><option>Hybrid</option><option>Onsite</option></select></div><div class="field"><label>Skills</label><input name="skills"></div><button class="btn btn-secondary">Filter</button></form><div id="results" class="grid"><div class="loading">Loading…</div></div>`,title);if($('[data-new]'))$('[data-new]').onclick=()=>route('/vendor/requirements/new');async function load(){try{const params=new URLSearchParams(new FormData($('#filters'))),rows=await api(mode==='vendor'?'/requirements/mine':mode==='partner'?'/partner/matching-requirements':`/requirements?${params}`);$('#results').innerHTML=rows.length?rows.map(r=>requirementCard(r,mode)).join(''):empty('⌕',mode==='vendor'?"You haven't posted any requirements yet.":'No active requirements match','Adjust your profile or filters and check again.');wireRequirementActions(mode)}catch(x){toast(x.message,true)}}$('#filters').onsubmit=e=>{e.preventDefault();load()};load()}
function wireRequirementActions(mode){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>route(`/${mode==='vendor'?'vendor':'partner'===mode?'partner':'candidate'}/${mode==='candidate'?'jobs':'requirements'}/${b.dataset.view}`));document.querySelectorAll('[data-start]').forEach(b=>b.onclick=async()=>{try{await api(`/partner/requirements/${b.dataset.start}/start`,{method:'POST'});toast('Requirement added to Working Requirements')}catch(x){toast(x.message,true)}});document.querySelectorAll('[data-apply]').forEach(b=>b.onclick=async()=>{try{await api(`/candidate/jobs/${b.dataset.apply}/apply`,{method:'POST'});toast('Application submitted');route('/candidate/applications')}catch(x){toast(x.message,true)}})}
function requirementForm(){layout(head('Post a requirement','Share a clear, country-aware hiring need with the network.')+`<form id="req" class="panel form-grid"><div class="field wide"><label>Job Title</label><input name="title" required></div><div class="field wide"><label>Job Description</label><textarea name="description" minlength="20" required></textarea></div><div class="field"><label>Country</label><select name="country" data-req-country required>${countries()}</select></div><div class="field"><label>State / Region</label><input name="state_region"></div><div class="field"><label>City / Location</label><input name="city" required></div><div class="field"><label>Work Mode</label><select name="work_mode"><option>Remote</option><option>Hybrid</option><option>Onsite</option></select></div><div class="field"><label>Employment Type</label><select name="employment_type" id="employment"></select></div><div class="field"><label>Status</label><select name="status"><option value="draft">Draft</option><option value="active">Active</option><option value="paused">Paused</option><option value="closed">Closed</option></select></div><div class="field"><label>Minimum Experience</label><input name="min_experience" type="number" min="0" step=".5" required></div><div class="field"><label>Maximum Experience</label><input name="max_experience" type="number" min="0" step=".5" required></div><div class="field wide"><label>Required Skills</label><input name="required_skills" placeholder="SQL, Power BI, Excel" required></div><div class="field wide"><label>Preferred Skills</label><input name="preferred_skills"></div><div class="field"><label>Number of Openings</label><input name="openings" type="number" min="1"></div><div class="field"><label>Application Deadline</label><input name="application_deadline" type="date"></div><div class="field"><label>Minimum Compensation</label><input name="compensation_min" type="number" min="0"></div><div class="field"><label>Maximum Compensation</label><input name="compensation_max" type="number" min="0"></div><div class="field"><label>Currency</label><input name="currency" id="currency"></div><div class="field"><label>Compensation Type</label><select name="compensation_type" id="compensation"></select></div><div class="actions wide"><button class="btn btn-primary">Publish Requirement</button><button type="button" class="btn btn-ghost" data-cancel>Cancel</button></div></form>`,'New Requirement');const c=$('[data-req-country]');function configure(){const x=countryConfig[c.value]||countryConfig.OT;$('#employment').innerHTML=x.employment.map(v=>`<option>${v}</option>`).join('');$('#compensation').innerHTML=x.compensation.map(v=>`<option>${v}</option>`).join('');$('#currency').value=x.currency}c.onchange=configure;configure();$('[data-cancel]').onclick=()=>route('/vendor/requirements');$('#req').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));['required_skills','preferred_skills'].forEach(k=>o[k]=o[k].split(',').map(x=>x.trim()).filter(Boolean));['min_experience','max_experience'].forEach(k=>o[k]=Number(o[k]));['openings','compensation_min','compensation_max'].forEach(k=>o[k]=o[k]?Number(o[k]):null);o.application_deadline=o.application_deadline||null;try{await api('/requirements',{method:'POST',body:JSON.stringify(o)});toast('Requirement created');route('/vendor/requirements')}catch(x){toast(x.message,true)}}}
async function detailPage(kind,id){try{const r=await api(`/requirements/${id}`);const actions=kind==='partner'?`<button class="btn btn-secondary" data-start="${id}">Start Working</button><button class="btn btn-primary" data-submit="${id}">Submit Candidate</button>`:kind==='candidate'?`<button class="btn btn-primary" data-apply="${id}">Apply Now</button>`:`<button class="btn btn-primary" data-subs>View Candidate Submissions</button>`;layout(head(r.title,`${r.company} · ${r.city}, ${countryConfig[r.country]?.name||r.country}`,actions)+`<div class="detail-grid"><section class="panel"><div class="chips">${r.required_skills.map(x=>`<span class="chip">${x}</span>`).join('')}</div><h3>About the requirement</h3><div class="description">${r.description}</div></section><aside class="panel"><div class="kv"><div><small>Status</small>${badge(r.status)}</div><div><small>Work Mode</small><b>${r.work_mode}</b></div><div><small>Employment</small><b>${r.employment_type}</b></div><div><small>Experience</small><b>${r.min_experience}–${r.max_experience} years</b></div><div><small>Openings</small><b>${r.openings||'Not specified'}</b></div><div><small>Posted</small><b>${new Date(r.created_at).toLocaleDateString()}</b></div></div></aside></div>`,'Requirement Detail');wireRequirementActions(kind);if($('[data-submit]'))$('[data-submit]').onclick=()=>route(`/partner/requirements/${id}/submit`);if($('[data-subs]'))$('[data-subs]').onclick=()=>route(`/vendor/requirements/${id}/submissions`)}catch(x){toast(x.message,true)}}
async function workingPage(){layout(head('Working Requirements','Requirements you have committed to source for.')+'<div id="results" class="grid"><div class="loading">Loading…</div></div>','Working Requirements');try{const rows=await api('/partner/working');$('#results').innerHTML=rows.length?rows.map(r=>requirementCard(r,'partner')).join(''):empty('◎','You are not working on any requirements yet.','Browse available requirements to get started.','<button class="btn btn-primary" data-browse>Browse Requirements</button>');wireRequirementActions('partner');if($('[data-browse]'))$('[data-browse]').onclick=()=>route('/partner/requirements')}catch(x){toast(x.message,true)}}
function candidateForm(reqId){layout(head('Submit a candidate','Create a candidate without requiring them to have a platform account.')+`<form id="candidate" class="panel form-grid"><div class="field"><label>Full Name</label><input name="full_name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Phone</label><input name="phone" required></div><div class="field"><label>Country</label><select name="country" data-country required>${countries()}</select></div><div class="field"><label>Current City / Location</label><input name="city" required></div><div class="field"><label>Current Job Title</label><input name="current_title" required></div><div class="field"><label>Total Experience</label><input name="total_experience" type="number" min="0" step=".5" required></div><div class="field"><label>Current Employer</label><input name="current_employer"></div><div class="field wide"><label>Key Skills</label><input name="skills" required></div><div class="field wide"><label>LinkedIn URL</label><input name="linkedin_url" type="url"></div><div id="country-extra" class="field wide"><div class="form-grid">${candidateExtra('IN')}</div></div><div class="field wide"><label>Resume (PDF, DOC or DOCX · max 5 MB)</label><input name="resume" type="file" accept=".pdf,.doc,.docx" required></div><button class="btn btn-primary wide">Create & Submit Candidate</button></form>`,'Candidate Submission');wireCountryFields();$('#candidate').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body={};for(const [k,v] of f)if(k!=='resume')body[k]=v;body.total_experience=Number(body.total_experience);body.skills=body.skills.split(',').map(x=>x.trim()).filter(Boolean);body.country_specific_data={};Object.keys(body).filter(k=>k.startsWith('extra_')).forEach(k=>{body.country_specific_data[k.slice(6)]=body[k];delete body[k]});try{const c=await api('/partner/candidates',{method:'POST',body:JSON.stringify(body)}),upload=new FormData();upload.append('file',f.get('resume'));await api(`/candidates/${c.id}/resume`,{method:'POST',body:upload});await api(`/partner/requirements/${reqId}/submit-candidate?candidate_id=${c.id}`,{method:'POST'});toast('Candidate submitted successfully');route('/partner/submissions')}catch(x){toast(x.message,true)}}}
async function candidatesPage(){layout(head('My Candidates','A simple candidate pool for people you created or submitted.')+'<div id="list" class="panel"><div class="loading">Loading…</div></div>','My Candidates');try{const rows=await api('/partner/candidates');$('#list').innerHTML=rows.length?table(['Candidate','Location','Experience','Skills','Resume'],rows.map(c=>[c.full_name,`${c.city}, ${countryConfig[c.country]?.name||c.country}`,`${c.total_experience} years`,c.skills.join(', '),c.resume_file_id?`<a class="text-link" href="/api/resumes/${c.resume_file_id}" data-resume="${c.resume_file_id}">Download</a>`:'Missing'])):empty('◇','No candidates yet','Candidates you create will appear here.');wireDownloads()}catch(x){toast(x.message,true)}}
const table=(heads,rows)=>`<div class="table-wrap"><table class="table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function wireDownloads(){document.querySelectorAll('[data-resume]').forEach(a=>a.onclick=async e=>{e.preventDefault();try{const r=await fetch(`${API}/resumes/${a.dataset.resume}`,{headers:{Authorization:`Bearer ${session.access_token}`}});if(!r.ok)throw Error('Unable to download resume');const blob=await r.blob(),u=URL.createObjectURL(blob),x=document.createElement('a');x.href=u;x.download='resume';x.click();URL.revokeObjectURL(u)}catch(x){toast(x.message,true)}})}
async function submissionsPage(kind,reqId){const title=kind==='vendor'?'Candidate Submissions':kind==='partner'?'My Submissions':'My Applications';layout(head(title,kind==='vendor'?'Review candidates and update the shared workflow status.':'Track live status updates from requirement vendors.')+'<div id="list" class="panel"><div class="loading">Loading…</div></div>',title);try{let path=kind==='vendor'?`/vendor/requirements/${reqId}/submissions`:kind==='partner'?'/partner/submissions':'/candidate/applications';const rows=await api(path);$('#list').innerHTML=rows.length?table(['Candidate','Requirement','Company / Submitted By','Source','Submitted','Status','Action'],rows.map(a=>[a.candidate.full_name,a.requirement.title,kind==='vendor'?(a.submitted_by.organization||a.submitted_by.name):a.requirement.company,a.submission_source==='candidate_self'?'Direct Application':'Sourcing Partner',new Date(a.submitted_at).toLocaleDateString(),badge(a.status),kind==='vendor'?`<button class="btn btn-secondary" data-review="${a.id}">Review</button>`:'—'])):empty('▤',kind==='candidate'?"You haven't applied to any jobs yet.":'No submissions yet',kind==='candidate'?'Browse available jobs to get started.':'Candidate submissions will appear here.');document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>route(`/vendor/submissions/${b.dataset.review}`))}catch(x){toast(x.message,true)}}
async function reviewPage(id){try{const a=await api(`/vendor/submissions/${id}`),c=a.candidate;layout(head(c.full_name,`${c.current_title} · ${c.city}, ${countryConfig[c.country]?.name||c.country}`)+`<div class="detail-grid"><section class="panel"><h3>Candidate profile</h3><div class="kv"><div><small>Email</small><b>${c.email}</b></div><div><small>Phone</small><b>${c.phone}</b></div><div><small>Experience</small><b>${c.total_experience} years</b></div><div><small>Skills</small><b>${c.skills.join(', ')}</b></div>${Object.entries(c.country_specific_data).map(([k,v])=>`<div><small>${k.replaceAll('_',' ')}</small><b>${v||'—'}</b></div>`).join('')}</div><div class="actions">${c.resume_file_id?`<a href="#" class="btn btn-secondary" data-resume="${c.resume_file_id}">Download Resume</a>`:'Resume missing'}</div></section><aside class="panel"><div class="eyebrow">${a.submission_source==='candidate_self'?'Direct Application':'Sourcing Partner'}</div><h3>${a.requirement.title}</h3><p class="muted">Submitted by ${a.submitted_by.organization||a.submitted_by.name}</p><form id="status" class="field"><label>Application Status</label><select name="status">${['submitted','under_review','shortlisted','interview','selected','rejected'].map(s=>`<option value="${s}" ${a.status===s?'selected':''}>${s.replace('_',' ')}</option>`).join('')}</select><button class="btn btn-primary">Save Status</button></form></aside></div>`,'Candidate Review');wireDownloads();$('#status').onsubmit=async e=>{e.preventDefault();try{await api(`/vendor/submissions/${id}/status`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('Status updated successfully')}catch(x){toast(x.message,true)}}}catch(x){toast(x.message,true)}}
async function profilePage(){const role=session.user.role;if(role==='candidate'){try{const c=await api('/candidate/profile');layout(head('My Profile','Keep your candidate information current.')+`<div class="panel"><div class="kv"><div><small>Name</small><b>${c.full_name}</b></div><div><small>Location</small><b>${c.city}, ${countryConfig[c.country]?.name}</b></div><div><small>Title</small><b>${c.current_title}</b></div><div><small>Experience</small><b>${c.total_experience} years</b></div><div><small>Skills</small><b>${c.skills.join(', ')}</b></div><div><small>Resume</small><b>${c.resume_file_id?'Uploaded':'Missing'}</b></div></div></div>`,'My Profile')}catch(x){toast(x.message,true)}}else layout(head('Profile','Your organization profile is linked to this account.')+`<div class="panel"><h3>${session.user.name}</h3><p class="muted">${roles[role].label} profile settings are ready for Phase 1 account data.</p></div>`,'Profile')}
async function resumePage(){try{const c=await api('/candidate/profile');layout(head('My Resume','Upload or replace your protected resume.')+`<form id="resume" class="panel"><div class="field"><label>Resume (PDF, DOC or DOCX · max 5 MB)</label><input name="file" type="file" accept=".pdf,.doc,.docx" required></div><div class="actions"><button class="btn btn-primary">${c.resume_file_id?'Replace':'Upload'} Resume</button>${c.resume_file_id?`<a href="#" class="btn btn-secondary" data-resume="${c.resume_file_id}">Download Current</a>`:''}</div></form>`,'My Resume');wireDownloads();$('#resume').onsubmit=async e=>{e.preventDefault();try{await api(`/candidates/${c.id}/resume`,{method:'POST',body:new FormData(e.target)});toast('Resume saved');resumePage()}catch(x){toast(x.message,true)}}}catch(x){toast(x.message,true)}}
requirementForm=function(){layout(head('Create requirement','Define the role, submission contract, and commercial terms before distribution.')+`<form id="req-v2" class="panel form-grid"><div class="field wide"><label>Job Title</label><input name="title" required></div><div class="field wide"><label>Job Description</label><textarea name="description" minlength="20" required></textarea></div><div class="field"><label>Country / Market</label><select name="country" data-req-country>${countries()}</select></div><div class="field"><label>State / Region</label><input name="state_region"></div><div class="field"><label>City</label><input name="city" required></div><div class="field"><label>Work Mode</label><select name="work_mode"><option>Remote</option><option>Hybrid</option><option>Onsite</option></select></div><div class="field"><label>Employment Type</label><select name="employment_type" id="employment"></select></div><div class="field"><label>Status</label><select name="status"><option value="active">Active</option><option value="draft">Draft</option></select></div><div class="field"><label>Minimum Experience</label><input name="min_experience" type="number" min="0" step=".5" required></div><div class="field"><label>Maximum Experience</label><input name="max_experience" type="number" min="0" step=".5" required></div><div class="field wide"><label>Mandatory Skills</label><input name="required_skills" required placeholder="Java, Spring Boot, AWS"></div><div class="field wide"><label>Preferred Skills</label><input name="preferred_skills"></div><div class="field"><label>Openings</label><input name="openings" type="number" min="1" value="1"></div><div class="field"><label>Submission Deadline</label><input name="submission_deadline" type="date"></div><div class="field wide"><label>Interview Process</label><input name="interview_process" placeholder="Technical screen → client panel"></div><div class="field"><label>Partner Payout</label><input name="payout_amount" type="number" min="0" required></div><div class="field"><label>Currency</label><input name="currency" id="currency" required></div><div class="field"><label>Payment Due (days after trigger)</label><input name="payment_timeline_days" type="number" min="0" value="30"></div><div class="field"><label>Replacement Period (days)</label><input name="replacement_period_days" type="number" min="0" value="60"></div><div class="field wide"><label>Required with every candidate</label><div class="check-grid">${[['resume','Resume'],['candidate_name','Name'],['email','Email'],['phone','Phone'],['candidate_interest_confirmation','Interest Confirmation'],['work_authorization','Work Authorization'],['notice_period','Notice Period'],['expected_compensation','Expected Salary / Rate']].map(([k,l],i)=>`<label><input type="checkbox" name="submission_fields" value="${k}" ${i<5?'checked':''}> ${l}</label>`).join('')}</div></div><button class="btn btn-primary wide">Create Requirement</button></form>`,'New Requirement');const country=$('[data-req-country]');function configure(){const cfg=countryConfig[country.value]||countryConfig.OT;$('#employment').innerHTML=cfg.employment.map(v=>`<option>${v}</option>`).join('');$('#currency').value=cfg.currency}country.onchange=configure;configure();$('#req-v2').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),o=Object.fromEntries(f);o.required_skills=o.required_skills.split(',').map(x=>x.trim()).filter(Boolean);o.preferred_skills=o.preferred_skills.split(',').map(x=>x.trim()).filter(Boolean);['min_experience','max_experience','openings'].forEach(k=>o[k]=Number(o[k]));o.submission_deadline=o.submission_deadline||null;o.application_deadline=null;o.compensation_min=null;o.compensation_max=null;o.compensation_type=null;o.submission_schema=f.getAll('submission_fields').map(key=>({key,label:key.replaceAll('_',' '),required:true}));o.commercial_terms={payout_amount:Number(o.payout_amount),currency:o.currency,payment_trigger:'candidate_joined',payment_timeline_days:Number(o.payment_timeline_days),replacement_period_days:Number(o.replacement_period_days)};['payout_amount','payment_timeline_days','replacement_period_days','submission_fields'].forEach(k=>delete o[k]);try{await api('/requirements',{method:'POST',body:JSON.stringify(o)});toast('Requirement created with versioned terms');route('/vendor/requirements')}catch(x){toast(x.message,true)}}}

reviewPage=async function(id){try{const a=await api(`/vendor/submissions/${id}`),c=a.candidate,e=a.evaluation||{};layout(head(c.full_name,`${c.current_title} · Submitted by ${a.submitted_by.organization||a.submitted_by.name}`)+`<div class="decision-strip"><div><small>HireScore</small><b>${e.final_score??'—'}/100</b></div><div><small>Fit</small><b>${e.fit_band||'Not evaluated'}</b></div><div><small>Availability</small><b>${a.availability.status.replaceAll('_',' ')}</b></div><div><small>Interest</small><b>${a.interest.status.replaceAll('_',' ')}</b></div><div><small>Eligibility</small><b>${a.eligibility.status.replaceAll('_',' ')}</b></div><div><small>Readiness</small><b>${a.readiness_status.replaceAll('_',' ')}</b></div></div><div class="detail-grid"><section class="panel"><h3>Evidence-backed evaluation</h3><p>${e.ranking_reason||'Evaluation pending.'}</p><div class="kv"><div><small>Mandatory matched</small><b>${e.mandatory_requirements?`${e.mandatory_requirements.matched}/${e.mandatory_requirements.total}`:'—'}</b></div><div><small>Missing requirements</small><b>${e.missing_requirements?.join(', ')||'None recorded'}</b></div><div><small>Provider</small><b>${e.provider||'—'}</b></div><div><small>Source</small><b>${a.submission_source==='sourcing_partner'?`Submitted by ${a.submitted_by.organization}`:'Direct applicant'}</b></div></div><h3>Candidate profile</h3><p>${c.total_experience} years · ${c.skills.join(', ')}</p>${c.resume_file_id?`<a href="#" class="btn btn-secondary" data-resume="${c.resume_file_id}">Download Resume</a>`:''}</section><aside class="panel"><form id="status" class="field"><label>Pipeline Status</label><select name="status">${['received','under_evaluation','qualified','ready_for_submission','shortlisted','interview','offer','joined','hold','rejected'].map(s=>`<option value="${s}" ${a.status===s?'selected':''}>${s.replaceAll('_',' ')}</option>`).join('')}</select><button class="btn btn-primary">Save Status</button></form>${a.submission_source==='sourcing_partner'?`<button class="btn btn-secondary" id="message-partner">Message ${a.submitted_by.organization}</button>`:''}</aside></div>`,'Candidate Decision');wireDownloads();$('#status').onsubmit=async ev=>{ev.preventDefault();await api(`/vendor/submissions/${id}/status`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(ev.target)))});toast('Pipeline updated')};if($('#message-partner'))$('#message-partner').onclick=async()=>{const x=await api('/conversations',{method:'POST',body:JSON.stringify({application_id:Number(id)})});route(`/vendor/messages?conversation=${x.id}`)}}catch(x){toast(x.message,true)}}

async function availabilityPage(){const [c,matchingStatus]=await Promise.all([api('/candidate/profile'),api('/candidate/matching-status')]),savedAvailability=matchingStatus.availability||{},options=[['actively_looking','◎','Actively looking','I want to hear about relevant opportunities now.'],['open_to_right_opportunity','✦','Open to the right role','Only notify me about strong, high-quality matches.'],['not_looking','◷','Not looking right now','Pause new opportunity alerts until I update this.'],['joined_elsewhere','✓','Joined elsewhere','Mark me unavailable and pause career matching.']];layout(`<div class="availability-workspace"><main class="availability-main"><section class="availability-hero"><div><span class="availability-eyebrow">CAREER SIGNAL</span><h1>Set your opportunity status</h1><p>Tell your AI Career Agent when and how you want to hear about new roles. You can change this at any time.</p><div class="availability-live"><i></i> Your status controls automatic matching</div></div><span class="availability-hero-icon">◷</span></section><form id="availability" class="availability-form"><section class="availability-card"><header><span>01</span><div><h2>Choose your current status</h2><p>This determines whether the agent should surface new opportunities.</p></div></header><div class="availability-options">${options.map(([value,icon,title,desc],index)=>`<label class="availability-option"><input type="radio" name="status" required value="${value}" ${savedAvailability.status===value?'checked':''}><span class="availability-option-icon">${icon}</span><span class="availability-option-copy"><b>${title}</b><small>${desc}</small></span><i>✓</i></label>`).join('')}</div></section><section class="availability-card availability-date-card"><header><span>02</span><div><h2>When can you start?</h2><p>Add an estimated date so matched employers receive accurate availability.</p></div></header><div class="availability-date-row"><div class="field"><label>Available from <i>Optional</i></label><input name="available_from" type="date" value="${savedAvailability.available_from||''}"></div><div class="date-guidance"><span>◷</span><p><b>Not sure about the exact date?</b><small>Leave it blank and your selected career status will still be saved.</small></p></div></div></section><div class="availability-action"><div><span>✦</span><p><b>AI matching preference</b><small id="availability-impact">Your agent will actively scan vendor requirements and notify you about relevant matches.</small></p></div><button class="btn btn-primary">Save availability</button></div></form></main><aside class="availability-aside"><section><span class="ai-mark">✦</span><h3>How your agent uses this</h3><p>Your availability is evaluated separately from your skills and job fit.</p><ul><li><span>✓</span><div><b>No effect on HireScore</b><small>Your fit score stays evidence-based.</small></div></li><li><span>✓</span><div><b>Controls opportunity alerts</b><small>Paused when you are unavailable.</small></div></li><li><span>✓</span><div><b>Always under your control</b><small>Update your status whenever it changes.</small></div></li></ul></section><section class="availability-privacy"><span>PRIVATE SIGNAL</span><h3>Your choice, your timing</h3><p>No application or profile sharing happens without your consent.</p></section><button class="profile-back" data-availability-dashboard>← Back to career workspace</button></aside></div>`,'Availability');$('[data-availability-dashboard]').onclick=()=>route('/candidate/dashboard');const impact=$('#availability-impact'),impactCopy={actively_looking:'Your agent will actively scan vendor requirements and notify you about relevant matches.',open_to_right_opportunity:'Your agent will surface only strong opportunities that closely match your profile.',not_looking:'New opportunity alerts will pause until you reactivate your search.',joined_elsewhere:'Career matching and opportunity alerts will remain paused.'};impact.textContent=impactCopy[savedAvailability.status]||'Choose and save your current availability.';document.querySelectorAll('input[name="status"]').forEach(x=>x.onchange=()=>impact.textContent=impactCopy[x.value]);$('#availability').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"],button.btn-primary'),body=Object.fromEntries(new FormData(e.target));body.available_from=body.available_from||null;button.disabled=true;button.textContent='Saving…';try{await api(`/candidates/${c.id}/availability`,{method:'PUT',body:JSON.stringify(body)});button.textContent='Availability saved ✓';button.disabled=false;toast('Availability updated successfully')}catch(x){button.disabled=false;button.textContent='Save availability';toast(x.message,true)}}}
async function payoutsPage(kind){const rows=await api(`/${kind}/payouts`);layout(head('Placements & Payouts','Status tracking only; no payment processing is connected.')+`<div class="panel">${rows.length?table(['Application','Candidate','Placement Verification','Payout','Amount'],rows.map(x=>[x.application_id,x.candidate_id,badge(x.placement_status),badge(x.status),`${x.currency} ${x.amount.toLocaleString()}`])):empty('₹','No payout records','Partner submissions create payout tracking automatically.')}</div>`,'Payouts')}
async function pipelinePage(){const rows=await api('/vendor/submissions'),stages=['received','under_evaluation','qualified','ready_for_submission','shortlisted','interview','offer','joined'];layout(head('Candidate Pipeline','Visibility remains available alongside conversational actions.')+`<div class="pipeline-board">${stages.map(s=>`<section class="pipeline-column"><h3>${s.replaceAll('_',' ')} <span>${rows.filter(x=>x.status===s).length}</span></h3>${rows.filter(x=>x.status===s).map(x=>`<button class="pipeline-item" data-review="${x.id}"><b>${x.candidate.full_name}</b><small>${x.requirement.title}</small></button>`).join('')}</section>`).join('')}</div>`,'Pipeline');document.querySelectorAll('[data-review]').forEach(x=>x.onclick=()=>route(`/vendor/submissions/${x.dataset.review}`))}
async function messagesPage(){const rows=await api('/conversations');const selected=Number(new URLSearchParams(location.search).get('conversation')||rows[0]?.id||0);let msgs=selected?await api(`/conversations/${selected}/messages`):[];layout(head('Partner Messages','Human client ↔ sourcing-partner conversations; separate from Ask HireScoreAI.')+`<div class="messages-layout"><aside class="panel">${rows.map(x=>`<button class="conversation-link ${x.id===selected?'active':''}" data-conversation="${x.id}">Conversation #${x.id}<small>${x.application_id?'Candidate submission':'Requirement'} context</small></button>`).join('')||'<p class="muted">Start a conversation from a partner candidate submission.</p>'}</aside><section class="panel"><div class="message-stream">${msgs.map(x=>`<div class="message ${x.sender_user_id===session.user.id?'mine':''}">${x.body}<small>${new Date(x.created_at).toLocaleString()}</small></div>`).join('')||'<p class="muted">No messages yet.</p>'}</div>${selected?`<form id="send" class="message-compose"><input name="body" placeholder="Write a contextual message…" required><button class="btn btn-primary">Send</button></form>`:''}</section></div>`,'Messages');document.querySelectorAll('[data-conversation]').forEach(x=>x.onclick=()=>{history.pushState({},'',`${location.pathname}?conversation=${x.dataset.conversation}`);messagesPage()});if($('#send'))$('#send').onsubmit=async e=>{e.preventDefault();await api(`/conversations/${selected}/messages`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});messagesPage()}}
async function sourcingPartnersPage(){layout(head('Sourcing Partners','Browse verified recruiters by name, agency, skill, role, or location.')+`<form id="partner-search" class="panel partner-search"><div class="field"><label>Search partners</label><input name="search" placeholder="Try Java, Bengaluru, Data Engineer…"></div><button class="btn btn-primary">Search</button></form><div id="partner-results" class="partner-browser"><div class="loading">Loading…</div></div>`,'Sourcing Partners');const load=async()=>{try{const term=$('#partner-search [name=search]').value.trim(),rows=await api(`/vendor/partners${term?`?search=${encodeURIComponent(term)}`:''}`);$('#partner-results').innerHTML=rows.length?rows.map(p=>`<article class="card partner-card"><div class="partner-card-head"><span class="avatar">${p.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</span><div><h3>${p.name}</h3><p>${p.agency_name||'Independent recruiter'}</p></div><span class="badge active">Verified</span></div><div class="meta"><span>⌖ ${p.city}, ${countryConfig[p.country]?.name||p.country}</span>${p.experience_years!=null?`<span>${p.experience_years} yrs experience</span>`:''}</div>${p.role_specializations.length?`<p class="partner-label">Specializes in</p><div class="chips">${p.role_specializations.slice(0,4).map(x=>`<span class="chip">${x}</span>`).join('')}</div>`:''}${p.skill_areas.length?`<p class="partner-label">Skills</p><div class="chips">${p.skill_areas.slice(0,6).map(x=>`<span class="chip">${x}</span>`).join('')}</div>`:''}</article>`).join(''):empty('⌕','No sourcing partners found','Try another skill, role, agency, or location.')}catch(x){toast(x.message,true)}};$('#partner-search').onsubmit=e=>{e.preventDefault();load()};load()}
function askPage(){layout(head('Ask HireScoreAI','Conversational client operations are intentionally limited until safe action handlers are implemented.')+`<div class="panel"><h3>Safe local boundary prepared</h3><p class="muted">The assistant will read structured requirements, submissions, evaluations, and partner performance. It will never invent candidate scores. Natural-language action execution is deferred from this MVP.</p></div>`,'Ask HireScoreAI')}
function placeholder(title,msg){layout(head(title,msg)+empty('◌','Deferred from this MVP',msg),title)}
function render(){document.querySelectorAll('[data-link]').forEach(()=>{});const p=location.pathname;if(!session){return p==='/auth/register'?registerPage():loginPage()}if(p.startsWith('/auth'))return route(roles[session.user.role].home);if(!rolePathAllowed(p))return route(roles[session.user.role].home);const m=p.match(/^\/(vendor|partner|candidate)\/(requirements|jobs)\/(\d+)$/);const submit=p.match(/^\/partner\/requirements\/(\d+)\/submit$/);const subs=p.match(/^\/vendor\/requirements\/(\d+)\/submissions$/);const review=p.match(/^\/vendor\/submissions\/(\d+)$/);if(m)return detailPage(m[1],m[3]);if(submit)return candidateForm(submit[1]);if(subs)return submissionsPage('vendor',subs[1]);if(review)return reviewPage(review[1]);if(p.endsWith('/dashboard'))return dashboard();if(p==='/vendor/requirements/new')return requirementForm();if(p==='/vendor/requirements')return requirementsPage('vendor');if(p==='/partner/requirements')return requirementsPage('partner');if(p==='/candidate/jobs')return requirementsPage('candidate');if(p==='/partner/working')return workingPage();if(p==='/partner/candidates')return candidatesPage();if(p==='/partner/submissions')return submissionsPage('partner');if(p==='/candidate/applications')return submissionsPage('candidate');if(p==='/candidate/profile'||p==='/partner/profile'||p==='/vendor/profile')return profilePage();if(p==='/candidate/resume')return resumePage();if(p==='/vendor/submissions')return placeholder('Candidate Submissions','Open a requirement to review its submissions.');if(p==='/vendor/partners')return sourcingPartnersPage();return route(roles[session.user.role].home)}
const navIcons={'Dashboard':'⌂','Home':'⌂','Requirements':'▣','Matching Requirements':'⌘','Working On':'◫','Candidate Inventory':'◇','Candidates':'◇','Submissions':'▤','My Applications':'▤','Placements & Payouts':'◎','Payouts':'◎','Messages':'✉','Profile':'○','My Profile':'○','Jobs':'⌕','Pipeline':'≋','Sourcing Network':'⌘','Sourcing Partners':'⌘','Ask HireScoreAI':'✦','Availability':'◷','My Resume':'▧'};
layout=function(content,title='HireScoreAI Network'){const links=nav[session.user.role],initials=session.user.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">H</span><span>HireScoreAI</span></div><nav class="nav">${links.map(([n,p])=>`<a href="${p}" data-link class="${location.pathname===p?'active':''}"><span class="nav-icon">${navIcons[n]||'·'}</span><span>${n}</span>${n==='Messages'?'<i class="nav-count">3</i>':''}</a>`).join('')}</nav><div class="partner-verification"><small>${roles[session.user.role].label}</small><b>${session.user.role==='sourcing_partner'?'Partner workspace':'Verified workspace'}</b><span>● Verified</span></div><div class="sidebar-footer"><span class="avatar">${initials}</span><div><div class="user-name">${session.user.name}</div><div class="user-role">${roles[session.user.role].label}</div></div><button class="logout" id="logout" title="Sign out">↗</button></div></aside><section class="content"><header class="topbar"><button class="topbar-menu mobile-toggle">☰</button><div class="global-search"><span>⌕</span><input aria-label="Global search" placeholder="Search candidates, requirements, clients…"><kbd>Ctrl K</kbd></div><div class="top-actions"><button class="ask-top" data-ask>✦ Ask HireScoreAI</button><button class="icon-button" title="Notifications">♧<i></i></button><span class="top-avatar">${initials}</span></div></header><div class="page">${content}</div></section></div>`;$('#logout').onclick=()=>{localStorage.removeItem('tb_session');session=null;route('/auth/login')};$('.mobile-toggle').onclick=()=>$('.sidebar').classList.toggle('open');if($('[data-ask]'))$('[data-ask]').onclick=()=>session.user.role==='requirement_vendor'?route('/vendor/ask'):toast('HireScoreAI assistant actions are being prepared for this role');const search=$('.global-search input');document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search?.focus()}},{once:true})};

const standardDashboard=dashboard;
dashboard=async function(){if(session.user.role!=='sourcing_partner')return standardDashboard();try{const [d,working,submissions,conversations,payouts]=await Promise.all([api('/dashboard'),api('/partner/working'),api('/partner/submissions'),api('/conversations'),api('/partner/payouts')]);const messageGroups=await Promise.all(conversations.slice(0,4).map(async c=>({conversation:c,messages:await api(`/conversations/${c.id}/messages`)})));const pendingPayouts=payouts.filter(x=>!['paid','not_eligible'].includes(x.status));const pendingAmount=pendingPayouts.reduce((sum,x)=>sum+Number(x.amount||0),0);const placementCount=payouts.filter(x=>['confirmed','verification_pending'].includes(x.placement_status)).length;const interviewCount=submissions.filter(x=>x.status==='interview').length;const kpis=[['briefcase','Active Requirements',d.available_requirements||0,'+'+(working.length||0)+' working'],['users','Candidates Submitted',d.applications||0,'Your total delivery'],['calendar','Interviews in Progress',interviewCount,'Live pipeline'],['check','Placements',placementCount,'Verified / pending'],['wallet','Pending Payouts',pendingAmount?`${pendingPayouts[0]?.currency||''} ${pendingAmount.toLocaleString()}`:'—',pendingPayouts.length+' pending']];const content=`<div class="partner-dashboard"><main class="dashboard-main"><div class="dashboard-greeting"><div><h1>Good ${new Date().getHours()<12?'morning':'afternoon'}, ${session.user.name.split(' ')[0]}! <span>👋</span></h1><p>Here’s your sourcing performance at a glance.</p></div></div><section class="kpi-grid">${kpis.map(([tone,label,value,trend])=>`<article class="kpi-card"><span class="kpi-icon ${tone}">${tone==='briefcase'?'▣':tone==='users'?'♙':tone==='calendar'?'□':tone==='check'?'✓':'₹'}</span><div><small>${label}</small><b>${value}</b><em>${trend}</em></div></article>`).join('')}</section><div class="dashboard-panels"><section class="dash-panel"><header><div><h2>Requirements I’m Working On</h2><p>Your active sourcing commitments</p></div><button data-view-all="/partner/working">View all</button></header><div class="requirement-list">${working.slice(0,4).map(r=>`<button class="requirement-row" data-requirement="${r.id}"><span class="row-icon">▣</span><span class="row-copy"><b>${r.title}</b><small>${r.company} · ${r.city}, ${r.country}</small></span><span class="row-meta"><i class="status-pill success">Actively Sourcing</i><small>${r.min_experience}–${r.max_experience} yrs</small></span><span class="chevron">›</span></button>`).join('')||`<div class="compact-empty"><span>⌘</span><b>No active sourcing commitments</b><p>Browse matched requirements and start working.</p><button class="btn btn-primary" data-view-all="/partner/requirements">Find requirements</button></div>`}</div></section><section class="dash-panel"><header><div><h2>Messages</h2><p>Latest client conversations</p></div><button data-view-all="/partner/messages">View all</button></header><div class="dashboard-message-list">${messageGroups.map(({conversation,messages})=>{const last=messages.at(-1);return `<button class="dashboard-message" data-conversation="${conversation.id}"><span class="message-avatar">C${conversation.id}</span><span><b>Client conversation</b><p>${last?.body||'No messages yet'}</p></span><small>${last?new Date(last.created_at).toLocaleDateString():''}</small></button>`}).join('')||`<div class="compact-empty"><span>✉</span><b>No conversations yet</b><p>Messages will appear after client engagement.</p></div>`}</div></section></div><section class="dash-panel submissions-panel"><header><div><h2>Recent Submissions</h2><p>Latest candidates delivered to clients</p></div><button data-view-all="/partner/submissions">View all</button></header>${submissions.length?`<div class="table-wrap"><table class="dashboard-table"><thead><tr><th>Candidate</th><th>Requirement</th><th>Client</th><th>Submitted On</th><th>Status</th></tr></thead><tbody>${submissions.slice(0,6).map(a=>`<tr><td><span class="candidate-cell"><i>${a.candidate.full_name.split(' ').map(x=>x[0]).slice(0,2).join('')}</i><b>${a.candidate.full_name}</b></span></td><td>${a.requirement.title}</td><td>${a.requirement.company}</td><td>${new Date(a.submitted_at).toLocaleDateString()}</td><td>${badge(a.status)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="compact-empty horizontal"><span>◇</span><div><b>No candidate submissions yet</b><p>Your newest submissions and client status updates will appear here.</p></div><button class="btn btn-secondary" data-view-all="/partner/candidates">Open inventory</button></div>`}</section></main><aside class="ai-command-panel"><header><div><span class="ai-mark">✦</span><div><b>HireScoreAI</b><small>Recruiting assistant</small></div></div><span class="online-dot">● Online</span></header><div class="ai-welcome"><span class="ai-orb">✦</span><div><b>Hi ${session.user.name.split(' ')[0]}! 👋</b><p>I can help you find matching roles, review requirements, and track your submissions.</p></div></div><div class="ai-quick-actions">${[['⌕','Find matching candidates','Search your inventory for a requirement','/partner/candidates'],['▤','Summarize requirement','Review must-haves and key details','/partner/requirements'],['✉','Draft client message','Prepare a professional response','/partner/messages'],['₹','Show payout status','Check invoices and payment updates','/partner/payouts'],['◷','What’s new today?','Highlights and recommended actions','/partner/dashboard']].map(([icon,label,desc,path])=>`<button data-ai-route="${path}"><span>${icon}</span><div><b>${label}</b><small>${desc}</small></div><i>›</i></button>`).join('')}</div><div class="ai-input"><input placeholder="Ask me anything…" aria-label="Ask HireScoreAI"><button>➤</button></div><p class="ai-disclaimer">AI suggestions use structured platform data. Scores are never invented.</p></aside></div>`;layout(content,'Dashboard');document.querySelectorAll('[data-view-all]').forEach(x=>x.onclick=()=>route(x.dataset.viewAll));document.querySelectorAll('[data-requirement]').forEach(x=>x.onclick=()=>route(`/partner/requirements/${x.dataset.requirement}`));document.querySelectorAll('[data-conversation]').forEach(x=>x.onclick=()=>route(`/partner/messages?conversation=${x.dataset.conversation}`));document.querySelectorAll('[data-ai-route]').forEach(x=>x.onclick=()=>route(x.dataset.aiRoute));const aiInput=$('.ai-input input'),aiSend=$('.ai-input button');aiSend.onclick=()=>{if(aiInput.value.trim())toast('Conversational actions are coming next; use the quick actions for now.')}}catch(x){toast(x.message,true)}};
function profileSelect(name,label,value,options){return `<div class="field"><label>${label} <i>Required</i></label><select name="extra_${name}" required><option value="">Select</option>${options.map(x=>`<option value="${x}" ${value===x?'selected':''}>${x}</option>`).join('')}</select></div>`}
function profileInput(name,label,value='',type='text',placeholder=''){return `<div class="field"><label>${label} <i>Required</i></label><input name="extra_${name}" type="${type}" value="${value||''}" placeholder="${placeholder}" required></div>`}
function profileCountryFields(code,data={}){if(code==='IN')return `${profileInput('preferred_location','Preferred Location',data.preferred_location,'text','Pune, Bengaluru, Remote')}${profileSelect('notice_period','Notice Period',data.notice_period,['Immediate','15 days','30 days','45 days','60 days','90 days'])}${profileInput('current_ctc','Current CTC',data.current_ctc,'text','8 LPA')}${profileInput('expected_ctc','Expected CTC',data.expected_ctc,'text','11 LPA')}${profileSelect('work_mode_preference','Work Mode Preference',data.work_mode_preference,['Remote','Hybrid','Onsite','Flexible'])}`;if(code==='US')return `${profileInput('state','State',data.state,'text','Virginia')}${profileSelect('work_authorization','Work Authorization',data.work_authorization,['US Citizen','Green Card','H1B','H4 EAD','L2 EAD','OPT','CPT','Other'])}${profileInput('availability','Availability',data.availability,'text','2 weeks')}${profileSelect('relocation_preference','Relocation Preference',data.relocation_preference,['Open','Not open','Within state','Case by case'])}${profileSelect('work_mode_preference','Work Mode Preference',data.work_mode_preference,['Remote','Hybrid','Onsite','Flexible'])}${profileSelect('employment_preference','Employment Preference',data.employment_preference,['W2','C2C','Full-Time','Contract','Contract-to-Hire'])}${profileInput('expected_rate','Expected Rate',data.expected_rate,'number','75')}${profileSelect('rate_type','Rate Type',data.rate_type,['Hourly','Annual'])}`;if(code==='GB')return `${profileInput('preferred_location','Preferred Location',data.preferred_location,'text','London, Manchester, Remote')}${profileSelect('notice_period','Notice Period',data.notice_period,['Immediate','1 week','2 weeks','1 month','2 months','3 months'])}${profileSelect('work_mode_preference','Work Mode Preference',data.work_mode_preference,['Remote','Hybrid','Onsite','Flexible'])}`;return `${profileInput('preferred_location','Preferred Location',data.preferred_location,'text','City or Remote')}${profileInput('availability','Availability',data.availability,'text','Available from…')}${profileSelect('work_mode_preference','Work Mode Preference',data.work_mode_preference,['Remote','Hybrid','Onsite','Flexible'])}`}
const readOnlyProfilePage=profilePage;profilePage=async function(){if(session.user.role!=='candidate')return readOnlyProfilePage();try{const c=await api('/candidate/profile'),countryName=countryConfig[c.country]?.name||c.country,initials=c.full_name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();layout(`<div class="profile-builder"><section class="profile-builder-main"><header class="profile-hero"><div class="profile-avatar-large">${initials}</div><div><span>COUNTRY-AWARE TALENT PROFILE</span><h1>Create your professional profile</h1><p>Your location controls which employment, compensation, and eligibility details the matching agent requires.</p></div><div class="profile-market"><small>Current market</small><b>${countryName}</b><em>AI matching enabled</em></div></header><form id="candidate-profile-form"><section class="profile-form-card"><header><span>01</span><div><h2>Identity & contact</h2><p>How employers and the matching agent identify you.</p></div></header><div class="profile-form-grid"><div class="field"><label>Full Name <i>Required</i></label><input name="full_name" value="${c.full_name}" required></div><div class="field"><label>Profile Email <i>Required</i></label><input name="email" type="email" value="${c.email}" required></div><div class="field"><label>Phone <i>Required</i></label><input name="phone" value="${c.phone}" required></div><div class="field"><label>LinkedIn URL</label><input name="linkedin_url" type="url" value="${c.linkedin_url||''}" placeholder="https://linkedin.com/in/..."></div></div></section><section class="profile-form-card"><header><span>02</span><div><h2>Career profile</h2><p>Core evidence used for title, skill, and experience matching.</p></div></header><div class="profile-form-grid"><div class="field"><label>Current Job Title <i>Required</i></label><input name="current_title" value="${c.current_title}" required></div><div class="field"><label>Total Experience (years) <i>Required</i></label><input name="total_experience" type="number" min="0" max="60" step=".5" value="${c.total_experience}" required></div><div class="field"><label>Current Employer</label><input name="current_employer" value="${c.current_employer||''}"></div><div class="field"><label>Skills <i>Required</i></label><input name="skills" value="${c.skills.join(', ')}" placeholder="SQL, Power BI, Excel" required></div></div></section><section class="profile-form-card location-card"><header><span>03</span><div><h2>Location & market details</h2><p>Country-specific fields update automatically when you change market.</p></div><div class="location-aware-badge">⌖ Location aware</div></header><div class="profile-form-grid"><div class="field"><label>Country <i>Required</i></label><select name="country" id="profile-country" required>${Object.entries(countryConfig).map(([code,cfg])=>`<option value="${code}" ${c.country===code?'selected':''}>${cfg.name}</option>`).join('')}</select></div><div class="field"><label>City / Location <i>Required</i></label><input name="city" value="${c.city}" required></div></div><div class="country-fields-head"><div><span id="country-flag">${c.country==='IN'?'🇮🇳':c.country==='US'?'🇺🇸':c.country==='GB'?'🇬🇧':'🌐'}</span><div><b id="country-fields-title">${countryName} hiring details</b><small>Required for accurate market matching</small></div></div><em>Fields adapt by country</em></div><div id="profile-country-fields" class="profile-form-grid country-specific-grid">${profileCountryFields(c.country,c.country_specific_data)}</div></section><div class="profile-save-bar"><div><span>✦</span><p><b>AI profile intelligence</b><small>Saving updates immediately refreshes your matching readiness.</small></p></div><button class="btn btn-primary">Save & analyse profile</button></div></form></section><aside class="profile-guidance"><div class="guidance-card"><span class="ai-mark">✦</span><h3>Why these details matter</h3><p>The agent uses structured, country-appropriate signals instead of guessing from your resume.</p><ul><li><span>✓</span> Better requirement matching</li><li><span>✓</span> Correct salary or rate context</li><li><span>✓</span> Eligibility-aware opportunities</li><li><span>✓</span> Fewer irrelevant alerts</li></ul></div><div class="market-guide"><span>YOUR MARKET</span><h3 id="guide-market">${countryName}</h3><p id="guide-copy">${c.country==='IN'?'CTC, notice period, preferred location, and work mode are used for Indian hiring.':c.country==='US'?'Work authorization, state, rate, employment type, and relocation are used for US hiring.':'Local availability and work preferences improve matching accuracy.'}</p></div><button class="profile-back" data-profile-dashboard>← Back to career workspace</button></aside></div>`,'My Profile');const country=$('#profile-country'),originalCountry=c.country;function updateCountryFields(){const code=country.value,data=code===originalCountry?c.country_specific_data:{};$('#profile-country-fields').innerHTML=profileCountryFields(code,data);const cfg=countryConfig[code]||countryConfig.OT;$('#country-fields-title').textContent=`${cfg.name} hiring details`;$('#country-flag').textContent=code==='IN'?'🇮🇳':code==='US'?'🇺🇸':code==='GB'?'🇬🇧':'🌐';$('#guide-market').textContent=cfg.name;$('#guide-copy').textContent=code==='IN'?'CTC, notice period, preferred location, and work mode are used for Indian hiring.':code==='US'?'Work authorization, state, rate, employment type, and relocation are used for US hiring.':code==='GB'?'Notice period, preferred location, and work mode are used for UK hiring.':'Availability, location, and work preferences improve matching accuracy.'}country.onchange=updateCountryFields;$('[data-profile-dashboard]').onclick=()=>route('/candidate/dashboard');$('#candidate-profile-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body={full_name:f.get('full_name').trim(),email:f.get('email').trim(),phone:f.get('phone').trim(),country:f.get('country'),city:f.get('city').trim(),current_title:f.get('current_title').trim(),total_experience:Number(f.get('total_experience')),skills:f.get('skills').split(',').map(x=>x.trim()).filter(Boolean),linkedin_url:f.get('linkedin_url')||null,current_employer:f.get('current_employer')||null,country_specific_data:{}};for(const [key,value] of f)if(key.startsWith('extra_'))body.country_specific_data[key.slice(6)]=value;try{await api('/candidate/profile',{method:'PUT',body:JSON.stringify(body)});toast('Profile saved and AI readiness refreshed');route('/candidate/dashboard')}catch(x){toast(x.message,true)}}}catch(x){toast(x.message,true)}};
function candidateAgentReply(prompt,status){const q=prompt.toLowerCase(),checks=status.profile_checks,matches=status.matches,missing=Object.entries(checks).filter(([,ready])=>!ready).map(([name])=>name);if(q.includes('profile')||q.includes('ready'))return missing.length?`Your matching profile is waiting for: ${missing.join(', ')}. Complete these items and I will automatically compare your profile with every active requirement.`:`Your profile, availability, and resume are complete. I am continuously comparing your structured profile with active requirements.`;if(q.includes('match')||q.includes('role')||q.includes('job'))return matches.length?`I found ${matches.length} strong profile match${matches.length===1?'':'es'}. Your best match is ${matches[0].title} at ${matches[0].company} with a ${Math.round(matches[0].match_score)}% structured match.`:'No strong match is available right now. You do not need to apply manually—I will keep checking when vendors add or update requirements.';if(q.includes('mail')||q.includes('email')||q.includes('alert'))return matches.length?`A match-email preview is ready for ${status.candidate.email}. Real delivery will start after the platform email provider is connected.`:`Email alerts will be prepared for ${status.candidate.email} as soon as I find a strong match.`;if(q.includes('resume'))return checks.resume?'Your resume is uploaded and included in profile readiness. Match scores still use structured profile evidence; resume claims are not invented.':'Your resume is missing. Upload PDF, DOC, or DOCX before matching can start.';return missing.length?`Complete ${missing.join(', ')} first. Then I can explain your matches and email-alert status.`:`Ask me about your profile readiness, strongest match, resume, or email alerts.`}
async function candidateDashboard(){try{const status=await api('/candidate/matching-status'),checks=status.profile_checks,matches=status.matches,ready=Object.values(checks).every(Boolean),steps=[['profile','Complete Profile','Add your title, skills, experience, and location.','/candidate/profile'],['availability','Set Availability','Tell the agent whether you are open to opportunities.','/candidate/availability'],['resume','Upload Resume','Add a protected PDF, DOC, or DOCX resume.','/candidate/resume']];const content=`<div class="partner-dashboard candidate-dashboard"><main class="dashboard-main"><div class="dashboard-greeting"><div><h1>Your AI job matching workspace <span>✦</span></h1><p>No job browsing or manual applications. Complete your profile once and the agent keeps checking vendor requirements for you.</p></div></div><section class="candidate-readiness ${ready?'ready':''}"><div><span class="readiness-ring">${Object.values(checks).filter(Boolean).length}/3</span><div><h2>${ready?'Profile ready for matching':'Finish your matching profile'}</h2><p>${ready?'The AI agent is actively comparing your profile with vendor requirements.':'Complete all three steps to activate automatic matching.'}</p></div></div><span class="badge ${ready?'active':''}">${ready?'Agent active':'Setup required'}</span></section><section class="readiness-grid">${steps.map(([key,title,desc,path],index)=>`<button class="step-card ${checks[key]?'complete':''}" data-candidate-route="${path}"><span>${checks[key]?'✓':index+1}</span><div><b>${title}</b><p>${desc}</p></div><i>${checks[key]?'Complete':'Open'} ›</i></button>`).join('')}</section><section class="dash-panel candidate-matches"><header><div><h2>AI Profile Matches</h2><p>Strong matches appear automatically—there is no Apply button.</p></div><span class="match-count">${matches.length} found</span></header>${!ready?`<div class="compact-empty horizontal"><span>✦</span><div><b>Matching is waiting</b><p>Complete your profile, availability, and resume to let the AI agent start.</p></div></div>`:matches.length?`<div class="match-list">${matches.map(m=>`<article class="passive-match"><div class="match-score"><b>${Math.round(m.match_score)}%</b><small>match</small></div><div class="match-copy"><span class="eyebrow">${m.company}</span><h3>${m.title}</h3><p>${m.city}, ${countryConfig[m.country]?.name||m.country} · ${m.work_mode} · ${m.min_experience}–${m.max_experience} yrs</p><div class="chips">${m.match_reasons.map(x=>`<span class="chip">${x}</span>`).join('')}</div></div><div class="email-alert"><span>✉</span><b>Email preview ready</b><small>${status.candidate.email}</small></div></article>`).join('')}</div>`:`<div class="compact-empty horizontal"><span>⌕</span><div><b>No strong match right now</b><p>The agent will keep checking automatically when vendors add new requirements.</p></div></div>`}</section><section class="email-channel-note"><span>✉</span><div><b>Email notification channel</b><p>${status.email_channel.message}</p></div><i>Development preview</i></section></main><aside class="ai-command-panel vendor-agent candidate-agent"><header><div><span class="ai-mark">✦</span><div><b>AI Career Agent</b><small>Passive opportunity matching</small></div></div><span class="online-dot">● ${ready?'Matching':'Waiting'}</span></header><div class="agent-thread"><div class="agent-bubble assistant"><span class="ai-orb">✦</span><div><b>Hi ${status.candidate.name.split(' ')[0]} 👋</b><p>${ready?`Your profile is ready. I found ${matches.length} strong match${matches.length===1?'':'es'} and will prepare email alerts for new opportunities.`:'Complete the checklist and I will start matching your profile automatically.'}</p></div></div></div><div class="agent-suggestions">${['Is my profile ready?','Show my best match','What about email alerts?','Check my resume'].map(x=>`<button data-candidate-prompt="${x}">${x}</button>`).join('')}</div><form class="ai-input" id="candidate-agent-form"><input placeholder="Ask about your profile or matches…" aria-label="Ask AI Career Agent"><button>➤</button></form><p class="ai-disclaimer">Matches use structured profile data. No application is submitted without a future consent workflow.</p></aside></div>`;layout(content,'Home');document.querySelectorAll('[data-candidate-route]').forEach(x=>x.onclick=()=>route(x.dataset.candidateRoute));const thread=$('.agent-thread'),input=$('#candidate-agent-form input');const ask=prompt=>{if(!prompt.trim())return;thread.insertAdjacentHTML('beforeend',`<div class="agent-bubble user"><p>${prompt}</p></div><div class="agent-bubble assistant"><span class="ai-orb">✦</span><p>${candidateAgentReply(prompt,status)}</p></div>`);thread.scrollTop=thread.scrollHeight;input.value=''};document.querySelectorAll('[data-candidate-prompt]').forEach(x=>x.onclick=()=>ask(x.dataset.candidatePrompt));$('#candidate-agent-form').onsubmit=e=>{e.preventDefault();ask(input.value)}}catch(x){toast(x.message,true)}}
candidateDashboard=async function(){try{const status=await api('/candidate/matching-status'),checks=status.profile_checks,matches=status.matches,completed=Object.values(checks).filter(Boolean).length,profilePercent=Math.round(completed/3*100),ready=completed===3,scanTime=new Date(status.last_scan_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),steps=[['profile','Professional profile','Skills, experience and preferences','/candidate/profile'],['availability','Career availability','Opportunity and joining status','/candidate/availability'],['resume','Verified resume','Protected source document','/candidate/resume']],events=[['profile','Profile data indexed',checks.profile?'Complete':'Action required'],['resume','Resume evidence check',checks.resume?'Indexed securely':'Upload required'],['availability','Availability signal',checks.availability?'Confirmed':'Reconfirmation needed'],['scan','Requirement scan',`${status.active_requirements_monitored} active roles monitored`]];const content=`<div class="partner-dashboard candidate-saas"><main class="dashboard-main"><section class="candidate-hero-card"><div class="candidate-hero-copy"><span class="saas-eyebrow">✦ AI-powered career workspace</span><h1>Good ${new Date().getHours()<12?'morning':'afternoon'}, ${status.candidate.name.split(' ')[0]}</h1><p>Your career agent works in the background—building your profile signal, monitoring vendor demand, and preparing alerts when a strong opportunity appears.</p><div class="hero-status-row"><span class="hero-status ${ready?'live':''}"><i></i>${ready?'Agent actively matching':'Complete setup to activate matching'}</span><span>Last scan ${scanTime}</span></div></div><div class="profile-strength"><div class="strength-ring" style="--progress:${profilePercent*3.6}deg"><span><b>${profilePercent}%</b><small>Profile strength</small></span></div><button data-candidate-route="${ready?'/candidate/profile':!checks.profile?'/candidate/profile':!checks.availability?'/candidate/availability':'/candidate/resume'}">${ready?'Review profile':'Complete setup'} ›</button></div></section><section class="candidate-metrics"><article data-search-status="${status.availability?.status || 'unknown'}"><span class="metric-icon violet">◎</span><div><small>Profile strength</small><b>${profilePercent}%</b><em>${ready?'Optimized for matching':'Setup in progress'}</em></div></article><article><span class="metric-icon blue">⌕</span><div><small>Roles monitored</small><b>${status.active_requirements_monitored}</b><em>Across active vendor demand</em></div></article><article><span class="metric-icon green">✦</span><div><small>Strong matches</small><b>${matches.length}</b><em>${matches.length?'Ready for your review':'Agent is watching'}</em></div></article><article><span class="metric-icon amber">✉</span><div><small>Email alerts</small><b>Preview</b><em>Provider connection pending</em></div></article></section><div class="candidate-two-col"><section class="saas-panel setup-checklist"><header><div><span class="section-kicker">PROFILE SETUP</span><h2>Matching readiness</h2><p>One profile powers every future opportunity.</p></div><span class="panel-progress">${completed} of 3 complete</span></header><div class="setup-progress"><i style="width:${profilePercent}%"></i></div><div class="setup-steps">${steps.map(([key,title,desc,path],index)=>`<button class="setup-step ${checks[key]?'complete':''}" data-candidate-route="${path}"><span>${checks[key]?'✓':index+1}</span><div><b>${title}</b><small>${desc}</small></div><i>${checks[key]?'Completed':'Continue'} →</i></button>`).join('')}</div></section><section class="saas-panel agent-activity"><header><div><span class="section-kicker">LIVE ACTIVITY</span><h2>Agent timeline</h2><p>What your career agent is checking.</p></div><span class="live-pulse">● Live</span></header><div class="activity-list">${events.map(([type,title,detail],index)=>`<div class="activity-item ${checks[type]||type==='scan'?'done':'pending'}"><span>${type==='scan'?'⌁':checks[type]?'✓':'!'}</span><div><b>${title}</b><small>${detail}</small></div><time>${index===3?scanTime:'Now'}</time></div>`).join('')}</div></section></div><section class="saas-panel opportunity-radar"><header><div><span class="section-kicker">OPPORTUNITY RADAR</span><h2>AI-curated profile matches</h2><p>No searching and no Apply button—only relevant opportunities surfaced by your agent.</p></div><span class="radar-count">${matches.length} strong match${matches.length===1?'':'es'}</span></header>${!ready?`<div class="radar-empty"><div class="radar-visual"><span></span><i></i><b>✦</b></div><div><h3>Your agent is almost ready</h3><p>Finish ${3-completed} remaining setup step${3-completed===1?'':'s'} to begin scanning ${status.active_requirements_monitored} active vendor requirements.</p><button class="btn btn-primary" data-candidate-route="${!checks.profile?'/candidate/profile':!checks.availability?'/candidate/availability':'/candidate/resume'}">Complete next step</button></div><ul><li><span>✓</span> Automatic requirement monitoring</li><li><span>✓</span> Evidence-based profile matching</li><li><span>✓</span> Email-ready opportunity alerts</li></ul></div>`:matches.length?`<div class="premium-match-list">${matches.map((m,index)=>`<article class="premium-match"><div class="rank-label">#${index+1} MATCH</div><div class="premium-score"><strong>${Math.round(m.match_score)}</strong><small>match score</small></div><div class="premium-match-copy"><span>${m.company}</span><h3>${m.title}</h3><p>⌖ ${m.city}, ${countryConfig[m.country]?.name||m.country} · ${m.work_mode} · ${m.min_experience}–${m.max_experience} yrs</p><div class="chips">${m.match_reasons.map(x=>`<span class="chip">${x}</span>`).join('')}</div></div><div class="alert-ready"><span>✉</span><b>Alert ready</b><small>${status.candidate.email}</small></div></article>`).join('')}</div>`:`<div class="radar-empty active"><div class="radar-visual"><span></span><i></i><b>⌕</b></div><div><h3>Monitoring the market</h3><p>Your profile is active. The agent scanned ${status.active_requirements_monitored} requirements and will surface the next strong match automatically.</p></div><ul><li><span>●</span> Profile agent active</li><li><span>●</span> Requirement monitoring live</li><li><span>●</span> Alerts ready when matched</li></ul></div>`}</section></main><aside class="ai-command-panel vendor-agent candidate-agent saas-agent"><header><div><span class="ai-mark">✦</span><div><b>AI Career Agent</b><small>Your always-on opportunity copilot</small></div></div><span class="online-dot">● ${ready?'Active':'Setup'}</span></header><div class="agent-health"><div><span class="agent-health-orb">✦</span><div><b>${ready?'Matching engine active':'Setup assistant active'}</b><small>${status.active_requirements_monitored} requirements in monitoring pool</small></div></div><span>${scanTime}</span></div><div class="agent-thread"><div class="agent-bubble assistant"><span class="ai-orb">✦</span><div><b>Here’s your status</b><p>${ready?`Your profile is ${profilePercent}% ready. I found ${matches.length} strong match${matches.length===1?'':'es'} and I’m monitoring new vendor requirements.`:`Your profile is ${profilePercent}% ready. Complete ${3-completed} more step${3-completed===1?'':'s'} and I’ll activate continuous matching.`}</p></div></div></div><div class="agent-suggestions"><button data-candidate-prompt="Is my profile ready?">Profile health</button><button data-candidate-prompt="Show my best match">Best match</button><button data-candidate-prompt="What about email alerts?">Email alerts</button><button data-candidate-prompt="Check my resume">Resume check</button></div><div class="agent-capabilities"><span>AGENT WORKSPACE</span><div><i>⌕</i><p><b>Demand monitoring</b><small>${status.active_requirements_monitored} active requirements</small></p></div><div><i>◎</i><p><b>Profile intelligence</b><small>${completed}/3 signals verified</small></p></div><div><i>✉</i><p><b>Opportunity alerts</b><small>Development preview channel</small></p></div></div><form class="ai-input" id="candidate-agent-form"><input placeholder="Ask your career agent…" aria-label="Ask AI Career Agent"><button>➤</button></form><p class="ai-disclaimer">Structured matching only. No application is submitted without consent.</p></aside></div>`;layout(content,'Career Workspace');document.querySelectorAll('[data-candidate-route]').forEach(x=>x.onclick=()=>route(x.dataset.candidateRoute));const thread=$('.agent-thread'),input=$('#candidate-agent-form input');const ask=prompt=>{if(!prompt.trim())return;thread.insertAdjacentHTML('beforeend',`<div class="agent-bubble user"><p>${prompt}</p></div><div class="agent-bubble assistant"><span class="ai-orb">✦</span><p>${candidateAgentReply(prompt,status)}</p></div>`);thread.scrollTop=thread.scrollHeight;input.value=''};document.querySelectorAll('[data-candidate-prompt]').forEach(x=>x.onclick=()=>ask(x.dataset.candidatePrompt));$('#candidate-agent-form').onsubmit=e=>{e.preventDefault();ask(input.value)};return status}catch(x){toast(x.message,true)}};
const candidateDashboardSaas = candidateDashboard;
candidateDashboard = async function () {
  return candidateDashboardSaas();
};
function vendorAgentReply(prompt,requirements,submissions,conversations){const q=prompt.toLowerCase(),active=requirements.filter(r=>r.status==='active'),sourced=submissions.filter(a=>a.submission_source==='sourcing_partner'),fresh=submissions.filter(a=>['received','submitted','under_evaluation'].includes(a.status));if(q.includes('candidate')||q.includes('submission'))return sourced.length?`${sourced.length} partner-sourced candidate${sourced.length===1?' is':'s are'} in your inbox. ${fresh.length} still need an initial review. Open a candidate row to see HireScore, availability, interest, and evidence.`:'No sourced candidates have arrived yet. When a sourcing partner submits someone, the candidate will appear instantly in the “New Candidate Inbox” below.';if(q.includes('requirement')||q.includes('role'))return active.length?`You have ${active.length} active requirement${active.length===1?'':'s'}: ${active.slice(0,3).map(r=>r.title).join(', ')}${active.length>3?' and more':''}. Each role stays separate, with its own candidate count and review flow.`:'You do not have an active requirement yet. Use “Post requirement” to create the first role.';if(q.includes('message')||q.includes('conversation'))return conversations.length?`There ${conversations.length===1?'is':'are'} ${conversations.length} active partner conversation${conversations.length===1?'':'s'}. Recent threads are visible on this dashboard and the complete inbox is under Messages.`:'There are no partner conversations yet. A conversation can start from a sourced candidate review or an accepted requirement context.';if(q.includes('today')||q.includes('attention')||q.includes('next'))return fresh.length?`Start with ${fresh.length} new candidate${fresh.length===1?'':'s'} awaiting review, then check ${active.length} active requirement${active.length===1?'':'s'} for coverage.`:`Your candidate inbox is clear. Review coverage across ${active.length} active requirement${active.length===1?'':'s'} or browse sourcing partners.`;return `I can summarize your requirements, show sourced candidates, highlight items needing attention, or open partner conversations. Try one of the suggested questions below.`}
async function vendorDashboard(){try{const [d,requirements,submissions,conversations]=await Promise.all([api('/dashboard'),api('/requirements/mine'),api('/vendor/submissions'),api('/conversations')]);const messageGroups=await Promise.all(conversations.slice(0,3).map(async c=>({conversation:c,messages:await api(`/conversations/${c.id}/messages`)})));const active=requirements.filter(r=>r.status==='active'),sourced=submissions.filter(a=>a.submission_source==='sourcing_partner'),reviewCount=submissions.filter(a=>['received','submitted','under_evaluation'].includes(a.status)).length,interviewCount=submissions.filter(a=>a.status==='interview').length;const kpis=[['briefcase','Active Requirements',active.length,`${requirements.length} total roles`],['users','Sourced Candidates',sourced.length,`${reviewCount} need review`],['calendar','Interviews',interviewCount,'Live pipeline'],['check','Selected',d.selected||0,'Hiring outcomes']];const content=`<div class="partner-dashboard vendor-dashboard"><main class="dashboard-main"><div class="dashboard-greeting"><div><h1>Good ${new Date().getHours()<12?'morning':'afternoon'}, ${session.user.name.split(' ')[0]}! <span>👋</span></h1><p>Your hiring workspace—requirements, sourced candidates, and partner conversations in one place.</p></div><button class="btn btn-primary" data-vendor-route="/vendor/requirements/new">＋ Post requirement</button></div><section class="kpi-grid vendor-kpis">${kpis.map(([tone,label,value,trend])=>`<article class="kpi-card"><span class="kpi-icon ${tone}">${tone==='briefcase'?'▣':tone==='users'?'♙':tone==='calendar'?'□':'✓'}</span><div><small>${label}</small><b>${value}</b><em>${trend}</em></div></article>`).join('')}</section><section class="dash-panel"><header><div><h2>Active Requirements</h2><p>Every role appears separately—open one to see its candidates.</p></div><button data-vendor-route="/vendor/requirements">View all</button></header><div class="requirement-list">${active.slice(0,5).map(r=>{const count=submissions.filter(a=>a.requirement.id===r.id).length;return `<button class="requirement-row" data-vendor-route="/vendor/requirements/${r.id}"><span class="row-icon">▣</span><span class="row-copy"><b>${r.title}</b><small>${r.city}, ${r.country} · ${r.work_mode}</small></span><span class="row-meta"><i class="status-pill success">${r.status}</i><small>${count} candidate${count===1?'':'s'}</small></span><span class="chevron">›</span></button>`}).join('')||`<div class="compact-empty horizontal"><span>▣</span><div><b>No active requirements</b><p>Post your first role to start receiving matched sourcing partners and candidates.</p></div><button class="btn btn-primary" data-vendor-route="/vendor/requirements/new">Post requirement</button></div>`}</div></section><section class="dash-panel submissions-panel"><header><div><h2>New Candidate Inbox</h2><p>Partner-sourced and direct candidates arrive here for review.</p></div><button data-vendor-route="/vendor/requirements">Open requirements</button></header>${submissions.length?`<div class="table-wrap"><table class="dashboard-table"><thead><tr><th>Candidate</th><th>Requirement</th><th>Source</th><th>HireScore</th><th>Status</th><th></th></tr></thead><tbody>${submissions.slice(0,7).map(a=>`<tr><td><span class="candidate-cell"><i>${a.candidate.full_name.split(' ').map(x=>x[0]).slice(0,2).join('')}</i><b>${a.candidate.full_name}</b></span></td><td>${a.requirement.title}</td><td>${a.submission_source==='sourcing_partner'?a.submitted_by.organization||'Sourcing partner':'Direct application'}</td><td>${a.evaluation?.final_score??'—'}</td><td>${badge(a.status)}</td><td><button class="table-action" data-review-candidate="${a.id}">Review</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="compact-empty horizontal"><span>◇</span><div><b>No candidates received yet</b><p>As soon as a sourcing partner submits a candidate, they will show here against the correct requirement.</p></div><button class="btn btn-secondary" data-vendor-route="/vendor/partners">Browse partners</button></div>`}</section><section class="dash-panel"><header><div><h2>Recent Partner Conversations</h2><p>Human messages stay connected to the relevant requirement or candidate.</p></div><button data-vendor-route="/vendor/messages">View all</button></header>${messageGroups.map(({conversation,messages})=>{const last=messages.at(-1);return `<button class="dashboard-message" data-conversation="${conversation.id}"><span class="message-avatar">P${conversation.partner_user_id}</span><span><b>Partner conversation</b><p>${last?.body||'Conversation created—send the first message.'}</p></span><small>${last?new Date(last.created_at).toLocaleDateString():''}</small></button>`}).join('')||`<div class="compact-empty horizontal"><span>✉</span><div><b>No partner conversations yet</b><p>Open a sourced candidate to begin a contextual conversation with its sourcing partner.</p></div><button class="btn btn-secondary" data-vendor-route="/vendor/messages">Open messages</button></div>`}</section></main><aside class="ai-command-panel vendor-agent"><header><div><span class="ai-mark">✦</span><div><b>AI Recruitment Agent</b><small>Conversational hiring workspace</small></div></div><span class="online-dot">● Online</span></header><div class="agent-thread"><div class="agent-bubble assistant"><span class="ai-orb">✦</span><div><b>Hi ${session.user.name.split(' ')[0]} 👋</b><p>I’m tracking ${active.length} active requirement${active.length===1?'':'s'} and ${submissions.length} candidate submission${submissions.length===1?'':'s'}. What would you like to review?</p></div></div></div><div class="agent-suggestions">${['Show new sourced candidates','Summarize my requirements','What needs attention today?','Show partner conversations'].map(x=>`<button data-agent-prompt="${x}">${x}</button>`).join('')}</div><form class="ai-input" id="vendor-agent-form"><input placeholder="Ask about candidates or requirements…" aria-label="Ask AI Recruitment Agent"><button>➤</button></form><p class="ai-disclaimer">Answers use live structured workspace data. Candidate scores are never invented.</p></aside></div>`;layout(content,'Dashboard');document.querySelectorAll('[data-vendor-route]').forEach(x=>x.onclick=()=>route(x.dataset.vendorRoute));document.querySelectorAll('[data-review-candidate]').forEach(x=>x.onclick=()=>route(`/vendor/submissions/${x.dataset.reviewCandidate}`));document.querySelectorAll('[data-conversation]').forEach(x=>x.onclick=()=>route(`/vendor/messages?conversation=${x.dataset.conversation}`));const thread=$('.agent-thread'),input=$('#vendor-agent-form input');const ask=prompt=>{if(!prompt.trim())return;thread.insertAdjacentHTML('beforeend',`<div class="agent-bubble user"><p>${prompt}</p></div><div class="agent-bubble assistant"><span class="ai-orb">✦</span><p>${vendorAgentReply(prompt,requirements,submissions,conversations)}</p></div>`);thread.scrollTop=thread.scrollHeight;input.value=''};document.querySelectorAll('[data-agent-prompt]').forEach(x=>x.onclick=()=>ask(x.dataset.agentPrompt));$('#vendor-agent-form').onsubmit=e=>{e.preventDefault();ask(input.value)}}catch(x){toast(x.message,true)}}
const roleDashboard=dashboard;dashboard=async function(){if(session.user.role==='requirement_vendor')return vendorDashboard();if(session.user.role==='candidate')return candidateDashboard();return roleDashboard()};
const baseRender=render;render=function(){const p=location.pathname;if(session){if(session.user.role==='candidate'&&(p==='/candidate/jobs'||p==='/candidate/applications'))return route('/candidate/dashboard');if(p==='/candidate/availability')return availabilityPage();if(p==='/vendor/payouts')return payoutsPage('vendor');if(p==='/partner/payouts')return payoutsPage('partner');if(p==='/vendor/pipeline')return pipelinePage();if(p==='/vendor/messages'||p==='/partner/messages')return messagesPage();if(p==='/vendor/ask')return askPage()}return baseRender()};
const availabilityPageCore=availabilityPage;availabilityPage=async function(){await availabilityPageCore();const last=document.querySelector('.availability-option:last-child');if(!last?.querySelector('input:checked'))last?.remove()};
// Keep presentation copy tied to the readiness state rendered from the API.
const candidateDashboardCore = candidateDashboard;
candidateDashboard = async function () {
  const chatStatus = await candidateDashboardCore();
  const root = document.querySelector('.candidate-saas');
  if (!root) return;
  const set = (element, selector, text) => {
    const target = element?.querySelector(selector);
    if (target) target.textContent = text;
  };
  const cards = [...root.querySelectorAll('.candidate-metrics article')];
  const steps = [...root.querySelectorAll('.setup-step')];
  const completed = Object.values(chatStatus.profile_checks).filter(Boolean).length;
  const remaining = steps.length - completed;
  const ready = remaining === 0;
  cards[1]?.remove();
  const searchStatuses = {
    actively_looking: ['Actively looking', 'Available for new opportunities'],
    open_to_right_opportunity: ['Open to the right role', 'Considering suitable opportunities'],
    not_looking: ['Not looking', 'Job matching is paused'],
    joined_elsewhere: ['Joined elsewhere', 'Job matching is paused'],
    needs_reconfirmation: ['Confirm availability', 'Please review your availability'],
    unknown: ['Not set', 'Set your availability to enable matching']
  };
  const availability = chatStatus.availability || {};
  const searchStatus = searchStatuses[availability.status] || searchStatuses.unknown;
  const paused = ['not_looking', 'joined_elsewhere'].includes(availability.status);
  const availableDate = availability.available_from && new Date(`${availability.available_from}T00:00:00`);
  const startDateText = availableDate && !Number.isNaN(availableDate.getTime())
    ? `Available from ${availableDate.toLocaleDateString('en-GB', {day: 'numeric', month: 'short', year: 'numeric'})}` : null;
  set(cards[0], 'small', 'Your availability');
  set(cards[0], 'b', searchStatus[0]);
  set(cards[0], 'em', !paused && startDateText ? startDateText : searchStatus[1]);
  cards[0]?.classList.add('search-status-metric');
  set(cards[2], 'small', 'Matching jobs');
  const missingChecks = Object.entries(chatStatus.profile_checks).filter(([,done]) => !done).map(([key]) => key);
  const pendingCopy = {profile: 'Complete your professional profile', resume: 'Upload your resume to enable matching', availability: 'Confirm availability to enable matching'};
  const matchCount = chatStatus.matches.length;
  set(cards[2], 'b', paused ? 'Paused' : !ready ? 'Setup required' : String(matchCount));
  set(cards[2], 'em', paused ? 'Update availability to resume matching'
    : !ready ? (missingChecks.length === 1 ? pendingCopy[missingChecks[0]] : `${missingChecks.length} setup steps need attention`)
    : matchCount ? 'Strong matches from the latest check' : `No strong matches across ${chatStatus.active_requirements_monitored} active roles`);
  cards[2]?.classList.toggle('matching-status-metric', !ready);
  set(cards[3], 'small', 'Email alerts');
  const emailChannel = chatStatus.email_channel?.status;
  const emailDisconnected = emailChannel === 'development_preview' || emailChannel === 'not_connected';
  set(cards[3], 'b', emailDisconnected ? 'Not connected' : 'Status unavailable');
  set(cards[3], 'em', emailDisconnected ? 'Real emails are not being sent' : 'Email delivery could not be verified');
  cards[3]?.classList.add('email-metric');
  const icons = [
    '<circle cx="12" cy="8" r="3"/><path d="M6 20v-2a6 6 0 0 1 12 0v2"/>',
    '<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12a22 22 0 0 0 18 0M12 11v3"/>',
    '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>'
  ];
  [cards[0], cards[2], cards[3]].forEach((card, index) => {
    const icon = card?.querySelector('.metric-icon');
    if (icon) icon.innerHTML = `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[index]}</svg>`;
  });
  const hero = root.querySelector('.candidate-hero-card');
  set(hero, '.saas-eyebrow', 'AI JOB MATCHING ASSISTANT');
  set(hero, 'p', 'Complete your profile once. The AI checks new jobs from recruiters, shows suitable matches here, and emails you when a strong opportunity appears.');
  const heroStatus = hero.querySelector('.hero-status');
  heroStatus.lastChild.textContent = ready ? ' AI is checking jobs for you' : ' Finish setup to start job matching';
  const checklist = root.querySelector('.setup-checklist');
  set(checklist, 'h2', 'Your next steps');
  set(checklist, 'header p', ready ? 'Your matching profile is complete.' : 'Complete your setup to enable matching.');
  set(checklist, '.panel-progress', `${completed} / ${steps.length} done`);
  const stepCopy = [
    ['Professional profile', 'Skills, experience and preferences'],
    ['Availability', 'Your current opportunity status'],
    ['Resume', 'Your supporting career document']
  ];
  steps.forEach((step, index) => {
    set(step, 'b', stepCopy[index][0]);
    set(step, 'small', stepCopy[index][1]);
    set(step, 'i', step.classList.contains('complete') ? 'Review →' : 'Complete →');
  });
  const activity = root.querySelector('.agent-activity');
  set(activity, 'h2', 'Matching overview');
  set(activity, 'header p', 'Latest checks on your profile.');
  set(activity, '.live-pulse', 'Latest scan');
  const activityRows = [...activity.querySelectorAll('.activity-item')];
  const activityCopy = [
    ['Profile details', steps[0].classList.contains('complete') ? 'Required details complete' : 'Required details missing'],
    ['Resume', steps[2].classList.contains('complete') ? 'Document uploaded' : 'Upload required'],
    ['Availability', steps[1].classList.contains('complete') ? 'Status confirmed' : 'Status required']
  ];
  activityCopy.forEach(([title, detail], index) => {
    set(activityRows[index], 'b', title);
    set(activityRows[index], 'small', detail);
  });
  set(activityRows[3], 'b', 'Recruiter requirements');
  const radar = root.querySelector('.opportunity-radar');
  set(radar, 'h2', 'Your opportunities');
  set(radar, 'header p', 'Strong matches based on your profile and preferences.');
  const empty = radar.querySelector('.radar-empty');
  if (empty && !ready) {
    set(empty, 'h3', 'Your next opportunity starts here');
    set(empty, 'p', `Complete ${remaining === 1 ? 'your remaining setup step' : `the remaining ${remaining} setup steps`} to compare your profile with open recruiter roles.`);
    set(empty, '.btn', 'Complete next step →');
  } else if (empty) {
    set(empty, 'h3', 'No strong matches yet');
    set(empty, 'p', 'Your profile is ready. Relevant opportunities will appear here when a strong match is available.');
  }
  initializeCandidateChat(root.querySelector('.saas-agent'), chatStatus);
};

document.addEventListener('click',e=>{const a=e.target.closest('[data-link]');if(a){e.preventDefault();route(a.getAttribute('href'))}});
// Candidate pages start after their workspace module has installed its views.
if(session?.user?.role!=='candidate')render();
